def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    if "ERPNext" in json.dumps({"l": lessons, "q": questions}):
        problems.append(f"  {name}: ERPNext branding leakage")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.168.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.167.0"' not in init:
        sys.exit("ABORT: not at v3.167.0.")
    for k in ("changes_updates", "email_integrations"):
        if k not in data:
            sys.exit(f"ABORT: {k} module not found in data file.")

    problems = _validate("SYS5", LESSONS_S5, QUESTIONS_S5, 9) + _validate("SYS6", LESSONS_S6, QUESTIONS_S6, 9)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    for name, lessons, questions, key, desc in (
        ("SYS 5", LESSONS_S5, QUESTIONS_S5, "changes_updates",
         "Updates and change control in ZhiftERP: the staged/documented/reversible discipline across the host's update stream and the site's customisations; the test site with its refresh rhythm and identity rules; the layer ladder from Customize Form through Custom Fields to scripts with the lowest-layer rule; the five-part customisation register and its annual reconciliation; the eight-step change procedure scaled by weight; and the twelve-minute smoke test with its amendment rule."),
        ("SYS 6", LESSONS_S6, QUESTIONS_S6, "email_integrations",
         "Channels in ZhiftERP: the channel rule and inventory; Letter Head and Print Settings with the specimen discipline; Print Formats by the three levels with nothing hard-typed; the domain sending identity on the Email Account record with the identity test; the Email Queue's daily glance, stuck-queue procedure, and volume read; scoped Notifications and Auto Email Reports with the annual review; and integration governance — dedicated users, credential custody, the register with health checks, and the quarterly door count, with the NGE Portal e-invoicing rail as the standing example."),
    ):
        bank = rebalance(list(questions))
        dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
        if max(dist.values()) > 10:
            print(f"ABORT — {name} spread failed: {dist}")
            sys.exit(1)
        total = sum(len(l["html"]) for l in lessons)
        print(f"{name} v3: {len(lessons)} chapters ({total:,} chars, min {min(len(l['html']) for l in lessons):,}), bank {len(bank)}, spread {dist}")
        if not CHECK_ONLY:
            data[key]["lessons"] = lessons
            data[key]["questions"] = bank
            data[key]["desc"] = desc

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.167.0"', '"3.168.0"'))
    print("  data: SYSADMIN 5 + 6 lessons + banks REPLACED (style v3, product-first)")
    print("wrote __version__ -> 3.168.0")


if __name__ == "__main__":
    main()
